"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import csv
import io
import json
import os
import re
import sys
import unicodedata


def norm_id(s):
    return str(s).strip().casefold() if False else str(s).strip().lower()


def norm_text(s):
    s = s.casefold()
    out = []
    for ch in s:
        cat = unicodedata.category(ch)
        if cat[0] == "L" or cat == "Nd":
            out.append(ch)
        else:
            out.append(" ")
    return " ".join("".join(out).split())


# ---------------------------------------------------------------- reading

def read_text(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        return f.read()


def parse_csv(path):
    text = read_text(path)
    lines = text.split("\n")
    meta = {}
    i = 0
    while i < len(lines):
        raw = lines[i].rstrip("\r")
        if raw.strip() == "":
            i += 1
            continue
        if raw.startswith("#"):
            body = raw[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
            continue
        break
    rest = "\n".join(lines[i:])
    rows = csv.reader(io.StringIO(rest, newline=""))
    header = None
    records = []
    for row in rows:
        if not row or all(c.strip() == "" for c in row):
            continue
        if header is None:
            header = [c.strip().lower() for c in row]
            continue
        cells = {}
        for name, val in zip(header, row):
            if name not in cells:
                cells[name] = val
        ballot = cells.get("ballot", "")
        contest = cells.get("contest", "").strip() if False else cells.get("contest", "")
        ranks = {}
        for name, val in cells.items():
            m = re.fullmatch(r"rank(\d+)", name)
            if not m:
                continue
            n = int(m.group(1))
            marks = []
            for part in val.split("|"):
                if part.strip() == "":
                    continue
                if part.lstrip()[:3].upper() == "WI:":
                    marks.append(("w", part.lstrip()[3:]))
                else:
                    marks.append(("c", part))
            if marks:
                ranks[n] = marks
        records.append((ballot, contest, ranks))
    return meta, records


def parse_jsonl(path):
    text = read_text(path)
    meta = None
    records = []
    for line in text.split("\n"):
        if line.strip() == "":
            continue
        obj = json.loads(line)
        if meta is None:
            meta = {str(k).lower(): v for k, v in obj.items()}
            continue
        ranks = {}
        for mk in obj.get("marks", []) or []:
            n = int(mk["rank"])
            if "write_in" in mk and mk["write_in"] is not None:
                ranks.setdefault(n, []).append(("w", str(mk["write_in"])))
            elif "candidate" in mk and mk["candidate"] is not None:
                ranks.setdefault(n, []).append(("c", str(mk["candidate"])))
        records.append((obj.get("ballot"), obj.get("contest"), ranks))
    return meta or {}, records


def load_batches(input_dir):
    cvr = os.path.join(input_dir, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            meta, records = parse_csv(path)
        elif name.endswith(".jsonl"):
            meta, records = parse_jsonl(path)
        else:
            continue
        batch = str(meta.get("batch", "")).strip()
        rev = int(str(meta.get("revision", "0")).strip())
        status = str(meta.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, records)
    out = []
    for batch in sorted(best):
        rev, status, records = best[batch]
        if status == "void":
            continue
        out.extend(records)
    return out


# --------------------------------------------------------------- counting

SKIP, PASS, CHOICE, OVER = 0, 1, 2, 3


def read_ballot(ranks, max_ranks, cand_ids, withdrawn, wi_lookup):
    """Return list of (kind, candidate) for rankings 1..max_ranks."""
    seen = set()
    out = []
    for n in range(1, max_ranks + 1):
        marks = ranks.get(n, [])
        cur = []
        for kind, val in marks:
            if kind == "w":
                c = wi_lookup.get(norm_text(val))
                if c is None:
                    continue
            else:
                c = norm_id(val)
            if c not in cur:
                cur.append(c)
        if not cur:
            out.append((SKIP, None))
            continue
        cur = [c for c in cur if c not in withdrawn]
        if not cur:
            out.append((PASS, None))
            continue
        left_b = cur
        cur = [c for c in cur if c not in seen]
        seen.update(left_b)
        if not cur:
            out.append((SKIP, None))
            continue
        if len(cur) == 1:
            out.append((CHOICE, cur[0]))
        else:
            out.append((OVER, None))
    return out


def count_for(rk, continuing):
    """Candidate the ballot counts for, or None when exhausted."""
    n = len(rk)
    for i in range(n):
        kind, c = rk[i]
        if kind == CHOICE:
            if c in continuing:
                return c
        elif kind == PASS:
            continue
        elif kind == OVER:
            return None
        else:  # SKIP
            if i + 1 < n and rk[i + 1][0] == SKIP:
                return None
    return None


def run_contest(contest, records):
    max_ranks = int(contest["max_ranks"])
    raw_ids = {}  # normalized -> id as written
    withdrawn = set()
    order = []
    for c in contest.get("candidates", []):
        k = norm_id(c["id"])
        raw_ids[k] = c["id"]
        if c.get("status", "active") == "withdrawn":
            withdrawn.add(k)
        else:
            order.append(k)
    wi_lookup = {}
    for w in contest.get("write_ins", []) or []:
        k = norm_id(w["id"])
        raw_ids[k] = w["id"]
        order.append(k)
        for t in [w["name"]] + list(w.get("aliases", []) or []):
            wi_lookup.setdefault(norm_text(t), k)
    lot = {norm_id(x): i for i, x in enumerate(contest.get("lot_order", []) or [])}

    ballots = [read_ballot(r, max_ranks, raw_ids, withdrawn, wi_lookup) for r in records]
    nb = len(ballots)
    # group identical readings
    groups = {}
    for b in ballots:
        groups[tuple(b)] = groups.get(tuple(b), 0) + 1

    continuing = set(order)
    history = []
    rounds = []
    winner = None
    while True:
        tallies = {c: 0 for c in continuing}
        for rk, cnt in groups.items():
            c = count_for(rk, continuing)
            if c is not None:
                tallies[c] += cnt
        active = sum(tallies.values())
        rnd = {"round": len(rounds) + 1,
               "tallies": {raw_ids[c]: v for c, v in tallies.items()},
               "exhausted": nb - active, "eliminated": []}
        rounds.append(rnd)
        history.append(tallies)
        if active == 0:
            break
        win = None
        for c, v in tallies.items():
            if 2 * v > active:
                win = c
        if win is None and len(continuing) == 1:
            win = next(iter(continuing))
        if win is not None:
            winner = raw_ids[win]
            break
        zeros = [c for c, v in tallies.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tallies.values())
            tied = [c for c, v in tallies.items() if v == m]
            r = len(history) - 2
            while len(tied) > 1 and r >= 0:
                h = history[r]
                mm = min(h[c] for c in tied)
                tied = [c for c in tied if h[c] == mm]
                r -= 1
            if len(tied) > 1:
